export const AGENT_DEFINITIONS: Record<string, string> = {
  "instructions/verification-openspec.md": "# OpenSpec verification\n\nCompare approved proposal, design, tasks, and requirements against assigned implementation scope. Report missing, incompatible, or out-of-scope behavior.\n",
  "instructions/verification-performance.md": "# Performance verification\n\nReview changed hot paths for measurable unbounded I/O/query/memory, N+1, repeated remote work, blocking, and accidental quadratic regressions. Skip speculative micro-optimization.\n",
  "instructions/verification-security.md": "# Security verification\n\nReview changed trust boundaries for introduced injection, authorization, secret, cryptography, and untrusted-input validation defects. Report concrete evidence only.\n",
  "instructions/verification-usability.md": "# Usability verification\n\nReview changed UI/assets for accessibility, responsive layout, visual token, component state, and interaction defects. Report introduced concrete defects only.\n",
  "instructions/triage.md": "# Verification triage\n\nThis instruction and the workflow protocol are already in your prompt — do not re-read them from disk.\n\nThe changed-file manifest is listed under Inputs in this assignment; the engine derives it from the same scope it validates. Do not run git to discover scope.\n\nSelect the minimum verifier roles that cover the change:\n\n| Role | Reviews |\n|---|---|\n| quality-verifier | Correctness, error handling, formatting/lint/type gates |\n| security-verifier | Trust boundaries, secrets, injection, permissions |\n| performance-verifier | Hot paths, resource use, latency regressions |\n| openspec-verifier | Conformance to the approved proposal/design/tasks/spec |\n| usability-verifier | UI/UX surfaces, accessibility, interaction defects |\n| test-verifier | NEVER select: the engine auto-launches the full test suite after the selected verifiers pass |\n\nScope each selected role to the changed files it must see. `hunks` is optional; use it only to bound large files. Reuse unchanged prior PASS evidence from the run outputs listed in the inputs. Do not review code, run checks, or launch verifiers.\n\nExample plan:\n\n```json\n{ \"roles\": [\n  { \"role\": \"quality-verifier\", \"reason\": \"runner correctness and gates\", \"files\": [\"src/runner.ts\", \"src/runner.test.ts\"] },\n  { \"role\": \"security-verifier\", \"reason\": \"new secret-handling boundary\", \"files\": [\"src/runner.ts\"] }\n] }\n```\n\nRouting is engine-owned (config); do not read workflow configuration, engine source, or other workflows' artifacts. Output only the run-bound triage plan.\n",
  "instructions/verification-quality.md": "# Quality verification\n\nRun the gates named in Required checks once (format/lint/type in a single command). Do not run tests or a build unless the checks list them. Review the scoped files for concrete correctness, maintainability, and error-handling defects.\n",
  "instructions/verification-test.md": "# Test verification\n\nRun the repository's complete configured test suite once, in a single command, then stop. Report introduced or unconfirmed failures as critical. Report confirmed unrelated pre-existing failures as info. Report no finding when the suite passes.\n",
  "instructions/verification.md": "# Verification\n\nScope: only the files listed in Step input (plus direct dependencies you must read to understand them). When the change touches engine internals, those files are the change surface — read them like any assigned file. Never explore git history, unrelated subsystems, library internals, workflow configuration, other workflows' artifacts, or run experiments outside the repository. These instructions and the protocol are already in your prompt — do not re-read them from disk.\n\nReuse prior PASS evidence from the planner/worker outputs listed in Inputs; re-run a gate only when the assigned files could invalidate that evidence. The engine auto-launches the test-verifier, which owns the complete test suite — never run the full suite yourself; use only the focused checks named for your role.\n\nWrite the run-bound findings payload; the engine derives the verdict. Critical findings block. Warning/info findings remain advisory. Never coordinate siblings, start the test verifier, choose a successor, edit code, or infer completion from runtime state.\n\nEvery finding must name the exact repository-relative `path` and the 1-based `line` in the current file where the defect appears.\n",
  "instructions/implementation.md": "# Implementation\n\nApply the assigned mode (`apply`, verifier fix, or developer-review fix). Read only the declared inputs and the files the change touches. Ask the planner through developer-visible chat when intent is unclear. If a task needs work beyond what the spec and tasks describe — or you are tempted to drop, narrow, or defer specified behavior to make it fit — surface the added scope and ask; do not absorb it silently.\n\nFor tests and APIs, mirror what the repository already does: read the sibling tests in `test/` that exercise similar surfaces (key simulation, mocks, dash components) before researching library internals. Do not dig through `node_modules` type definitions, inspect git history or other commits, or explore other workflows' artifacts.\n\nRun focused tests covering the changed behavior. Mark each OpenSpec task complete only after focused validation. After the change is complete, run `bun run type-check` and `bun run build` once each; the test-verifier owns the full suite — do not run it. Do not commit, push, archive, or launch agents.\n",
  "instructions/workflow-agent-protocol.md": "# Managed workflow protocol\n\nComplete only assigned run. Workflow engine owns lifecycle, roles, successors, and effects.\n\n- Never start agents or mutate workflow state.\n- Use scoped repository tools only. No filesystem-global searches.\n- Write only declared output artifact. Include assigned run and schema identity.\n- Report exactly one allowed outcome with `agentic-coding workflow handoff`.\n- Runtime status, chat, and file existence do not complete run.\n- On blocker, submit bounded blocker message. Never choose recipient or next step.\n",
  "instructions/archive.md": "# Archive\n\nYour run environment is already set: `$HERDR_CHANGE_ID`, `$HERDR_OUTPUT`, and the other HERDR_* variables identify this run. Do not re-read run.env, workflow state, or list the repository to discover the change id.\n\nRun exactly these commands — no help or discovery needed:\n\n```bash\nopenspec validate \"$HERDR_CHANGE_ID\" --strict\nopenspec archive \"$HERDR_CHANGE_ID\" --yes\n```\n\nIf archive fails, the change most likely modifies existing requirements without merge markers. Fix only structural issues: add `## MODIFIED Requirements` or `## REMOVED Requirements` sections to the affected spec(s) matching the approved proposal, then re-run validate and archive. Never change requirement or scenario content. If it still fails, report blocked with the exact error.\n\nAfter a successful archive, verify once with `git status --short` and `openspec validate --all`. Report the archive result and the validated files in your run-bound evidence. Do not author documentation, alter knowledge metadata, perform human verification, or perform any review-comment revision. Do not commit, push, or clean up the workspace.\n\nIf archival fails because the change is already archived, report that exact state rather than repeating archival. Keep the archive step limited to OpenSpec lifecycle duties; documentation is handled and reviewed by its dedicated preceding step.\n",
  "instructions/fusion-consolidation.md": "# Plan fusion\n\nYou receive the validated plan drafts from every fusion planner under Inputs — read each one from disk; none may be skipped. Fuse them into one consolidated OpenSpec proposal; do not concatenate them.\n\nReconcile before writing:\n\n- Prefer convergent choices — the approach most drafts agree on wins by default.\n- Where drafts conflict, pick the single strongest approach and record the rejected alternatives with the reason they lost in the proposal's design notes.\n- Carry each draft's `risks` that still applies into the artifacts. Answer every `questions` entry you can from the repository; surface the remainder as explicit open questions in the design.\n- Never blend incompatible half-measures from different drafts into one plan.\n\nThen create the normal OpenSpec change artifacts exactly as the planning step does. The change directory does not exist at run start. Create it first — this is the only setup command, no other openspec CLI exploration is needed:\n\n```bash\nopenspec new change \"$HERDR_CHANGE_ID\" --description \"<one-line summary>\"\n```\n\nThen let openspec drive the artifact set instead of assuming it:\n\n```bash\nopenspec status --change \"$HERDR_CHANGE_ID\" --json\n```\n\nParse the JSON: `artifactPaths` gives each artifact's `resolvedOutputPath`, and the `requires` edges give the build order. Create every required artifact in dependency order; for each, use:\n\n```bash\nopenspec instructions <artifact-id> --change \"$HERDR_CHANGE_ID\" --json\n```\n\nUse the returned `template` as the structure and follow `instruction` and `rules` (constraints for you — never copy them into the file). Read dependency artifacts from disk before writing the next one. Re-run `openspec status --change \"$HERDR_CHANGE_ID\" --json` until every required artifact exists.\n\nWhen reconciling implementation tasks or required validation, preserve focused, change-relevant checks that cover the changed behavior. Do not require the worker to run the complete repository test suite or add a complete-suite worker task. The workflow-owned `test-verifier` runs the complete configured repository test suite after implementation and selected verifier checks complete; do not prescribe a repository-wide test command in the consolidated plan.\n\nFinish with `openspec validate \"$HERDR_CHANGE_ID\" --strict`. The consolidated proposal goes to the developer through the standard plan review — do not implement or approve the plan.\n\nConsult `agentic-coding workflow wiki search` and `show` while reconciling; wiki reads are exempt from the file-scope restriction. Weight status, trust tier, and staleness, preferring verified stable concepts over contradictory drafts and recording that reason in design notes. Identify the project context for evidence: use `projects/<project-id>/<concept>` for facts specific to one project, and use `shared/<concept>` only for claims covering multiple projects with evidence from every covered project. Repository-relative source paths must be labeled with the project whose concept documents them, never presented as universal locations or rules. Search and read before deciding, update existing concepts in place in any future documentation step, and do not create active near-duplicates. Do not write wiki concepts from consolidation; report durable documentation gaps in the consolidated plan for the dedicated wiki step, which writes unverified drafts and leaves promotion to human approval.\n",
  "instructions/planning-fusion.md": "# Fusion planning\n\nYou are one of several independent planners producing a parallel plan draft for the same objective. Your run environment is already set: `$HERDR_CHANGE_ID` and the other HERDR_* variables identify this run. Do not re-read run.env, run `agentic-coding workflow status`, or inspect `.herdr-workflow` state — the engine owns the workflow.\n\nAn independent perspective is the point: do not coordinate with sibling planners, read their outputs, or soften your recommendation to hedge. Do not create or modify OpenSpec artifacts — consolidation happens in a later step.\n\nStudy the objective and read only the files the change touches plus their direct dependencies. Then write your plan draft as the run output artifact against `core.plan-draft@1`, following exactly this output style:\n\n- `approach` — a concise summary of the implementation strategy: what will be built, in what order, and why this shape.\n- `files` — one entry per file you would create or change; each has a repository-relative `path` and the concrete `change` for that file. Plan at file level; every entry must be actionable.\n- `risks` — one `{ \"detail\": ... }` entry per risk: anything that could make this plan fail, break consumers, or regress behavior.\n- `questions` — one `{ \"detail\": ... }` entry per open question you could not resolve from the repository alone.\n\nWhen proposing implementation tasks or required validation, require focused, change-relevant checks that cover the changed behavior. Do not require the worker to run the complete repository test suite or add a complete-suite worker task. The workflow-owned `test-verifier` runs the complete configured repository test suite after implementation and selected verifier checks complete; do not prescribe a repository-wide test command in the plan draft.\n\nBe decisive: commit to one approach instead of listing alternatives. Free-form prose outside these sections will be rejected by the output schema. Output only the run-bound plan draft.\n\nWiki reads are explicitly exempt from the read-only-files-the-change-touches restriction: consult `agentic-coding workflow wiki search` and `show`, and weight results by status, trust tier, and staleness. Identify the project before interpreting evidence: use `projects/<project-id>/<concept>` for project-specific knowledge, and reserve `shared/<concept>` for cross-project claims supported by evidence from every covered project. Repository-relative source paths are valid only in the context of the project named by the concept, never as universal locations or rules. Search and read before deciding, update existing concepts in place in any future documentation step, and avoid active near-duplicates. Do not write wiki concepts: parallel planners must not coordinate through shared writes; put knowledge gaps in this draft's `risks` or `questions` for the dedicated wiki step.\n",
  "instructions/planning.md": "# Planning\n\nYour run environment is already set: `$HERDR_CHANGE_ID` and the other HERDR_* variables identify this run. Do not re-read run.env, run `agentic-coding workflow status`, or inspect `.herdr-workflow` state — the engine owns the workflow.\n\nThe change directory does not exist at run start. Create it first — this is the only setup command, no other openspec CLI exploration is needed:\n\n```bash\nopenspec new change \"$HERDR_CHANGE_ID\" --description \"<one-line summary>\"\n```\n\nThen let openspec drive the artifact set instead of assuming it:\n\n```bash\nopenspec status --change \"$HERDR_CHANGE_ID\" --json\n```\n\nParse the JSON: `artifactPaths` gives each artifact's `resolvedOutputPath`, and the `requires` edges give the build order. Track the artifacts with your todo list.\n\nCreate every required artifact in dependency order. For each:\n\n```bash\nopenspec instructions <artifact-id> --change \"$HERDR_CHANGE_ID\" --json\n```\n\nUse the returned `template` as the structure, follow `instruction` and `rules` (constraints for you — never copy them into the file), and write to `resolvedOutputPath`. Read the completed dependency artifacts from disk before writing the next one — always from disk, never from memory. After each artifact, re-run `openspec status --change \"$HERDR_CHANGE_ID\" --json` until every required artifact exists.\n\nUnderstand the task's domain surface: read only the files the change touches and their direct dependencies. Do not explore workflow-engine internals (workflow/, tui/dash engine plumbing), git history archaeology, other workflows' change directories, or archived changes for reference.\n\nFinish with `openspec validate \"$HERDR_CHANGE_ID\" --strict`. Output artifact must identify validated files and evidence. Do not implement or approve plan.\n\n## Validation ownership\n\nWhen defining implementation tasks or required validation, require focused, change-relevant checks that cover the changed behavior. Do not require the worker to run the complete repository test suite or add a complete-suite worker task. The workflow-owned `test-verifier` runs the complete configured repository test suite after implementation and selected verifier checks complete; do not prescribe a repository-wide test command in planning artifacts.\n\n## Revising after plan review\n\nWhen the plan gate returns the workflow to planning (a plan review requested changes), the run context carries the review comments. Read them with `agentic-coding workflow status --json`: the current `step.context.comments` array lists each comment with `comment` (body), `file`, and optional `line`/`startLine`/`endLine` pointing at the reviewed artifact.\n\nRevise the plan against those comments, not around them:\n- Re-read the flagged artifacts from disk, apply each comment to the relevant artifact, and record which comment each edit resolves.\n- If a comment is genuinely invalid or already satisfied, say so explicitly in your summary rather than silently ignoring it.\n- Do not introduce unrelated changes while revising.\n- Keep the artifact set in sync — re-run `openspec status --change \"$HERDR_CHANGE_ID\" --json` after editing and re-validate with `openspec validate \"$HERDR_CHANGE_ID\" --strict`.\n\nThe revision runs on the same change directory; the engine preserved the previous plan artifacts for you to amend in place.\n\n## Knowledge wiki\n\nConsult durable context with `agentic-coding workflow wiki search` and `show` before deciding; wiki reads are explicitly exempt from the do-not-explore restriction. Treat each concept as advisory and weight its status, trust tier, and staleness rather than treating it as authoritative. Identify the project before recording facts: use `projects/<project-id>/<concept>` for knowledge specific to one project or repository, and use `shared/<concept>` only for claims that apply across projects and have evidence from every covered project. A repository-relative source path is meaningful only in the context of the project named by its concept; never present it as a universal location or rule. Search and read before deciding, update existing concepts in place in any future documentation step, and do not create active near-duplicates. Do not write wiki concepts from planning. Report useful documentation gaps in the plan's risks or questions for the dedicated wiki step; that step owns draft authoring and human approval owns promotion.\n",
  "instructions/wiki.md": "# Wiki documentation\n\nYou are the dedicated documentation (wiki) agent. Your job is to turn durable knowledge from the completed change into useful OKF v0.2 concept documents before archival. You are not the planner, implementer, verifier, reviewer, or archivist.\n\n## Research before writing\n\n- Inspect the repository evidence available to this run and the change artifacts, but stay within the assignment's scope.\n- Consult the centralized bundle with `agentic-coding workflow wiki search` and `agentic-coding workflow wiki show <concept-id>` before writing. Search for related concepts first; do not create an active near-duplicate when an existing concept can be updated in place.\n- Treat existing concepts as advisory. Weigh `status`, trust tier, and staleness: a verified stable concept is stronger evidence than an unverified draft, deprecated concept, or stale concept. Resolve contradictions from repository evidence and explain the choice in your run evidence.\n- Identify the project that owns each fact. Use `projects/<project-id>/<concept>` for project-specific knowledge. Use `shared/<concept>` only for a claim that genuinely applies to multiple projects and has evidence from every covered project.\n- A repository-relative source path is meaningful only in the context of the project whose concept documents it. Label that project in the source or body citation; never present a path from one repository as a universal location or rule.\n\n## Authoring OKF drafts\n\nUse the existing `agentic-coding workflow wiki write` operation. Write valid UTF-8 Markdown with OKF v0.2-compatible YAML frontmatter and meaningful body content. Every authored concept must have a non-empty `type`, `title`, `description`, `sources` with source resources, and body-level claims supported by citations to those resources. Include the change resource automatically supplied by the CLI and cite concrete repository files or other evidence in the body. Preserve unknown frontmatter fields, update existing concepts in place when one is the intended subject, and do not create active near-duplicates. Mark workflow-authored concepts as `status: draft` with generated provenance.\n\nNever set `status: stable`, add `verified` metadata, impersonate a human or verification actor, or invoke verification. Never run an archival command, modify OpenSpec archival state, or claim that documentation is human-verified. Human promotion happens only after developer approval through the engine-owned `wiki.verify` effect.\n\nIf the change contains no durable knowledge worth retaining, write no concept and explicitly report `no durable knowledge found` in your run-bound evidence. Otherwise report every touched concept identifier, whether it was created or updated, and the source-backed fact it records.\n\n## Review-comment revisions\n\nWhen the assignment context contains wiki review comments, treat it as a revision of the drafts you authored:\n\n1. Read every named concept again with `wiki show`, including the requested concept and line anchor when supplied.\n2. Apply each valid comment to the named concept without discarding unrelated correct content. Keep the concept an unverified draft.\n3. Record which comment identifier or anchor each edit resolves. If a comment is invalid, names a missing concept, or is already satisfied, report that explicitly rather than silently ignoring it.\n4. Report the touched concept identifiers and unresolved comments in the run-bound evidence.\n\nA review revision changes documentation only. Do not archive, verify, or perform human promotion yourself. Finish through the normal generic workflow handoff with one allowed outcome.\n",
  "bridges/opencode-telemetry.js": "const fs = require('node:fs');\nconst path = require('node:path');\n// Deterministic env backstop: herdr's agent spawn may give this process a stale\n// pane env (see pi-telemetry.ts). The isolated config dir encodes the run id:\n// .herdr-workflow/runtime-config/<runId>/, so recover run.env from it when the\n// pane env did not arrive.\nfunction recoverRunEnv() {\n  try {\n    const xdg = process.env.XDG_CONFIG_HOME;\n    if (!xdg) return;\n    const runId = path.basename(xdg);\n    if (!/^[0-9a-f-]{36}$/.test(runId)) return;\n    const file = path.join(process.cwd(), '.herdr-workflow', 'runtime-bin', runId, 'run.env');\n    const content = fs.readFileSync(file, 'utf8');\n    for (const line of content.split('\\n')) {\n      const match = line.match(/^([A-Za-z_][A-Za-z0-9_]*)=(.*)$/);\n      if (!match) continue;\n      process.env[match[1]] = match[2].replace(/^'|'$/g, '');\n    }\n  } catch {}\n}\nrecoverRunEnv();\nconst SECRET_PATTERN = /(-----BEGIN[\\s\\S]*?-----END[^\\n]*|sk-[A-Za-z0-9_-]{16,}|gh[pousr]_[A-Za-z0-9]{16,}|AKIA[0-9A-Z]{16}|xox[baprs]-[A-Za-z0-9-]{10,}|github_pat_[A-Za-z0-9_]{20,}|HERDR_RUN_TOKEN=[^\\s]+)/g;\nconst redact = text => text.replace(SECRET_PATTERN, '[REDACTED]');\nfunction emit(event, fields = {}) {\n  const output = process.env.HERDR_TELEMETRY_PATH;\n  const envelope = { schemaVersion: 1, at: new Date().toISOString(), layer: 'runtime', runtime: 'opencode', event, workflowId: process.env.HERDR_WORKFLOW_ID, runId: process.env.HERDR_RUN_ID, stepId: process.env.HERDR_STEP_ID, role: process.env.HERDR_ROLE, profile: process.env.HERDR_PROFILE, traceparent: process.env.TRACEPARENT, ...fields };\n  if (output) try { fs.mkdirSync(path.dirname(output), { recursive: true }); fs.appendFileSync(output, JSON.stringify(envelope) + '\\n'); } catch {}\n  const endpoint = process.env.OTEL_EXPORTER_OTLP_ENDPOINT; if (endpoint) void fetch(`${endpoint.replace(/\\/$/, '')}/v1/logs`, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify(envelope), signal: AbortSignal.timeout(750) }).catch(() => undefined);\n}\n// Telemetry only: runtime lifecycle events. Handoff and checks go through the\n// agent's normal tools (`agentic-coding workflow handoff`).\nmodule.exports = async () => ({ event: async ({ event }) => emit(`runtime.${event.type}`, { sessionId: event.properties?.sessionID }) });\n",
  "bridges/opencode-v2-telemetry.js": "const fs = require('node:fs');\nconst path = require('node:path');\n// Deterministic env backstop: herdr's agent spawn may give this process a stale\n// pane env (see pi-telemetry.ts). The isolated config dir encodes the run id:\n// .herdr-workflow/runtime-config/<runId>/, so recover run.env from it when the\n// pane env did not arrive.\nfunction recoverRunEnv() {\n  try {\n    const xdg = process.env.XDG_CONFIG_HOME;\n    if (!xdg) return;\n    const runId = path.basename(xdg);\n    if (!/^[0-9a-f-]{36}$/.test(runId)) return;\n    const file = path.join(process.cwd(), '.herdr-workflow', 'runtime-bin', runId, 'run.env');\n    const content = fs.readFileSync(file, 'utf8');\n    for (const line of content.split('\\n')) {\n      const match = line.match(/^([A-Za-z_][A-Za-z0-9_]*)=(.*)$/);\n      if (!match) continue;\n      process.env[match[1]] = match[2].replace(/^'|'$/g, '');\n    }\n  } catch {}\n}\nrecoverRunEnv();\nconst SECRET_PATTERN = /(-----BEGIN[\\s\\S]*?-----END[^\\n]*|sk-[A-Za-z0-9_-]{16,}|gh[pousr]_[A-Za-z0-9]{16,}|AKIA[0-9A-Z]{16}|xox[baprs]-[A-Za-z0-9-]{10,}|github_pat_[A-Za-z0-9_]{20,}|HERDR_RUN_TOKEN=[^\\s]+)/g;\nconst redact = text => text.replace(SECRET_PATTERN, '[REDACTED]');\nfunction emit(event, fields = {}) {\n  const output = process.env.HERDR_TELEMETRY_PATH;\n  const envelope = { schemaVersion: 1, at: new Date().toISOString(), layer: 'runtime', runtime: 'opencode-v2', event, workflowId: process.env.HERDR_WORKFLOW_ID, runId: process.env.HERDR_RUN_ID, stepId: process.env.HERDR_STEP_ID, role: process.env.HERDR_ROLE, profile: process.env.HERDR_PROFILE, traceparent: process.env.TRACEPARENT, ...fields };\n  if (output) try { fs.mkdirSync(path.dirname(output), { recursive: true }); fs.appendFileSync(output, JSON.stringify(envelope) + '\\n'); } catch {}\n  const endpoint = process.env.OTEL_EXPORTER_OTLP_ENDPOINT; if (endpoint) void fetch(`${endpoint.replace(/\\/$/, '')}/v1/logs`, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify(envelope), signal: AbortSignal.timeout(750) }).catch(() => undefined);\n}\n// Telemetry only: runtime lifecycle events. Handoff and checks go through the\n// agent's normal tools (`agentic-coding workflow handoff`).\nmodule.exports = async () => ({ event: async ({ event }) => emit(`runtime.${event.type}`, { sessionId: event.properties?.sessionID }) });\n",
  "bridges/pi-telemetry.ts": "import type { ExtensionAPI } from '@earendil-works/pi-coding-agent';\nimport { appendFileSync, mkdirSync, readFileSync } from 'node:fs';\nimport { dirname, join } from 'node:path';\n\n// Deterministic env backstop: herdr's agent spawn does not reliably inherit the\n// pane shell env (first agent start often fails with \"not an available shell\"\n// and the retry spawns in a stale tracked shell, giving the agent another run's\n// environment). The engine writes .herdr-workflow/runtime-bin/by-agent/<name>\n// pointing at the current run's run.env before every launch and every\n// reused-prompt delivery, so recover keyed off this process's own --name\n// identity — works for persistent-role and round-scoped names alike.\nfunction recoverRunEnv(): void {\n  try {\n    const nameIndex = process.argv.indexOf('--name');\n    const name = nameIndex >= 0 ? process.argv[nameIndex + 1] : undefined;\n    if (!name || !/^[a-z][a-z0-9_-]*$/.test(name)) return;\n    const pointer = join(process.cwd(), '.herdr-workflow', 'runtime-bin', 'by-agent', name);\n    const relative = readFileSync(pointer, 'utf8').trim();\n    if (!relative) return;\n    const content = readFileSync(join(process.cwd(), relative), 'utf8');\n    for (const line of content.split('\\n')) {\n      const match = line.match(/^([A-Za-z_][A-Za-z0-9_]*)=(.*)$/);\n      if (!match) continue;\n      process.env[match[1]!] = match[2]!.replace(/^'|'$/g, '');\n    }\n  } catch { /* best effort */ }\n}\nrecoverRunEnv();\n\nconst output = process.env.HERDR_TELEMETRY_PATH;\nconst SECRET_PATTERN = /(-----BEGIN[\\s\\S]*?-----END[^\\n]*|sk-[A-Za-z0-9_-]{16,}|gh[pousr]_[A-Za-z0-9]{16,}|AKIA[0-9A-Z]{16}|xox[baprs]-[A-Za-z0-9-]{10,}|github_pat_[A-Za-z0-9_]{20,}|HERDR_RUN_TOKEN=[^\\s]+)/g;\nfunction redact(text: string): string { return text.replace(SECRET_PATTERN, '[REDACTED]') }\nfunction emit(event: string, fields: Record<string, unknown> = {}) {\n  const envelope = { schemaVersion: 1, at: new Date().toISOString(), layer: 'runtime', runtime: 'pi', event, workflowId: process.env.HERDR_WORKFLOW_ID, runId: process.env.HERDR_RUN_ID, stepId: process.env.HERDR_STEP_ID, role: process.env.HERDR_ROLE, profile: process.env.HERDR_PROFILE, traceparent: process.env.TRACEPARENT, ...fields };\n  if (output) try { mkdirSync(dirname(output), { recursive: true }); appendFileSync(output, JSON.stringify(envelope) + '\\n'); } catch { /* observational */ }\n  const endpoint = process.env.OTEL_EXPORTER_OTLP_ENDPOINT; if (endpoint) void fetch(`${endpoint.replace(/\\/$/, '')}/v1/logs`, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify(envelope), signal: AbortSignal.timeout(750) }).catch(() => undefined);\n}\nexport default function bridge(pi: ExtensionAPI) {\n  // Telemetry only: runtime lifecycle + usage events. Handoff and checks go\n  // through the agent's normal tools (`agentic-coding workflow handoff`).\n  // Wall-clock start of the in-flight assistant message, used to derive per-\n  // message generation duration and tokens/s on message_end.\n  let assistantStartedAt: number | undefined;\n  pi.on('agent_start', () => { assistantStartedAt = undefined; emit('runtime.started'); });\n  pi.on('agent_settled', () => emit('runtime.settled'));\n  pi.on('tool_execution_end', (event: { toolName?: string; isError?: boolean }) => emit('runtime.tool', { tool: event.toolName, outcome: event.isError ? 'error' : 'ok' }));\n  pi.on('message_start', (event: { message?: { role?: string } }) => {\n    if (event.message?.role === 'assistant') assistantStartedAt = Date.now();\n  });\n  pi.on('message_end', (event: { message?: { role?: string; usage?: { input?: number; output?: number; cacheRead?: number; cacheWrite?: number; cost?: { total?: number } } } }) => {\n    const usage = event.message?.usage;\n    if (event.message?.role !== 'assistant' || !usage) return;\n    const durationMs = assistantStartedAt !== undefined ? Math.max(0, Date.now() - assistantStartedAt) : undefined;\n    assistantStartedAt = undefined;\n    // Omit fields the runtime did not provide rather than emitting zeros:\n    // downstream consumers treat absent fields as \"not measurable\".\n    emit('runtime.usage', {\n      inputTokens: usage.input,\n      outputTokens: usage.output,\n      ...(typeof usage.cacheRead === 'number' ? { cacheReadTokens: usage.cacheRead } : {}),\n      ...(typeof usage.cacheWrite === 'number' ? { cacheWriteTokens: usage.cacheWrite } : {}),\n      cost: usage.cost?.total,\n      ...(durationMs !== undefined && durationMs > 0 ? {\n        durationMs,\n        ...(usage.output ? { tokensPerSecond: Math.round((usage.output / durationMs) * 10000) / 10 } : {}),\n      } : {}),\n    });\n  });\n}\n"
};
